import{_ as a,o,c as t,a2 as r}from"./chunks/framework.Boholvbs.js";const s="/docs/screenshots/table.png",m=JSON.parse('{"title":"Table view","description":"","frontmatter":{},"headers":[],"relativePath":"guide/table.md","filePath":"guide/table.md","lastUpdated":1791713513000}'),l={name:"guide/table.md"};function n(i,e,c,d,h,b){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="table-view" tabindex="-1">Table view <a class="header-anchor" href="#table-view" aria-label="Permalink to &quot;Table view&quot;">​</a></h1><p>The table view renders your JSON as a table. Switch to it using the <strong>table</strong> tab in the header (route <code>/table</code>). Paste JSON in the working editor on the left and the table appears on the right.</p><p><img src="'+s+'" alt="Table view"></p><h2 id="how-json-becomes-a-table" tabindex="-1">How JSON becomes a table <a class="header-anchor" href="#how-json-becomes-a-table" aria-label="Permalink to &quot;How JSON becomes a table&quot;">​</a></h2><ul><li>An <strong>array of objects</strong> becomes one row per element, with a column for every property found across the array. Missing properties are left empty.</li><li>An <strong>array of simple values</strong> (strings, numbers, booleans) becomes a single <code>value</code> column.</li><li>A <strong>single object</strong> becomes a table with <code>key</code> and <code>value</code> columns.</li><li>Any other scalar value is shown alone.</li><li><strong>Nested objects and arrays</strong> are rendered as smaller tables inside the cell. Arrays of primitive values inside a cell are shown comma separated.</li><li>An empty array renders as <code>[]</code>; an empty object renders as <code>{}</code>.</li></ul><h2 id="toolbars" tabindex="-1">Toolbars <a class="header-anchor" href="#toolbars" aria-label="Permalink to &quot;Toolbars&quot;">​</a></h2><p>The left toolbar is the same editor toolbar as on the home view (search, paste from clipboard, upload a JSON file, delete all). The right side has the table controls described below.</p><h2 id="searching-in-the-table" tabindex="-1">Searching in the table <a class="header-anchor" href="#searching-in-the-table" aria-label="Permalink to &quot;Searching in the table&quot;">​</a></h2><p>Type in the search box to filter the rows.</p><ul><li>The search is <strong>case-insensitive</strong> and checks every column, including nested values.</li><li>Search a specific column with <code>column:value</code>, for example <code>index:0</code> keeps only the rows where the <code>index</code> column matches <code>0</code>. The column name is matched case-insensitively and can be abbreviated (<code>idx:0</code> also matches <code>index</code>).</li><li>For a key/value table (single object), the columns are <code>key</code> and <code>value</code>, so you can search <code>key:name</code> or <code>value:true</code>.</li><li>Matching is <strong>fuzzy</strong> by default: the characters of the term only need to appear in order, so <code>mse</code> matches <code>Mouse</code>. This applies to both the column name and the value.</li><li>Turn on <strong>Exact match</strong> to require the value to be exactly the term (ignoring case) instead of fuzzy matching. For example, <code>index:0</code> with exact match keeps only the rows where the index is <code>0</code>, not <code>10</code>.</li><li>Rows without a match are hidden and <strong>No matching data</strong> is shown when nothing matches.</li><li>The counter next to the search box shows how many rows are currently displayed (for example <code>2 rows</code>) and updates while you type.</li></ul><h2 id="full-screen" tabindex="-1">Full screen <a class="header-anchor" href="#full-screen" aria-label="Permalink to &quot;Full screen&quot;">​</a></h2><p>Use <strong>Full screen</strong> to expand the table to the whole page, and <strong>Exit full screen</strong> to go back.</p>',12)])])}const p=a(l,[["render",n]]);export{m as __pageData,p as default};
